-- Additive campaign expansion. Existing puzzle identities and records are immutable.
begin;

-- CATALOG_SEED_BEGIN (generated by scripts/export-catalog.mjs)
-- CATALOG_SEED_END

-- Keep the validated v1/v2 save implementation private; the public wrapper
-- additionally fences writes from clients that do not know the expanded catalog.
alter function public.save_game_progress(jsonb, integer) set schema svela_private;
alter function svela_private.save_game_progress(jsonb, integer) rename to save_game_progress_v2;
revoke all on function svela_private.save_game_progress_v2(jsonb, integer) from public, anon, authenticated, service_role;

create function public.save_game_progress(p_save jsonb, p_expected_revision integer, p_catalog_version text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := svela_private.require_account();
  v_current public.game_progress%rowtype;
begin
  select * into v_current from public.game_progress where user_id = v_uid;
  -- A stale revision must still return the ordinary conflict response. A current
  -- old client may keep playing the first 15, but cannot erase expanded progress.
  if found and v_current.revision = p_expected_revision
    and p_catalog_version is distinct from 'fantasy-v2'
    and exists (
      select 1 from svela_private.puzzle_catalog c where c.catalog_version = 'fantasy-v2'
      and (v_current.save->>'activeLevel' = c.level_key
        or v_current.save->'completed' ? c.level_key
        or v_current.save->'levels' ? c.level_key
        or v_current.save->'bestTimes' ? c.level_key)
    ) then
    raise exception 'Update Svela before saving progress for this campaign' using errcode = '22023';
  end if;
  return svela_private.save_game_progress_v2(p_save, p_expected_revision);
end;
$$;
revoke all on function public.save_game_progress(jsonb, integer, text) from public, anon, authenticated, service_role;
grant execute on function public.save_game_progress(jsonb, integer, text) to authenticated;
commit;
